"""Fictional-only backend tests. Every generated byte stays below work/v2/python.

Run: python3 -B -m unittest discover -s tests -p test_posix_core.py -v
Native cleanup tests run only on a capable POSIX host. Never live collection.
"""
from __future__ import annotations
import copy
import contextlib
import csv
import io
import json
import os
import stat
import sys
sys.dont_write_bytecode = True
import subprocess
import types
import unittest
from unittest import mock
import uuid
import zipfile
import importlib.util
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).absolute().parent.parent
sys.path.insert(0, str(ROOT / "scripts"))
from posix_core import Toolkit, Refusal, BACKEND, digest, encoded, decode, native_capable, relative, timestamp, safe_read
import posix_core as core
import private_workspace


def private_capability_hold(error):
    return str(error) in {
        "Private storage refused: private-linux-foreign-filesystem",
        "Private storage refused: private-linux-abi-unavailable",
        "Private storage refused: private-linux-libc-unavailable",
        "Private storage refused: private-platform-unavailable",
        "Private storage refused: private-darwin-acl-api-unavailable",
        "Private storage refused: private-darwin-acl-platform-unavailable",
        "Private storage refused: private-darwin-acl-not-empty",
    }


class BackendTests(unittest.TestCase):
    def setUp(self):
        parent = ROOT / "work" / "v2" / "python"
        parent.mkdir(parents=True, exist_ok=True)
        self.root = parent / ("fixture-" + uuid.uuid4().hex)
        (self.root / "templates").mkdir(parents=True)
        for rel in ("toolkit.json", "templates/ledger-contract.json", "templates/report.html"):
            (self.root / rel).write_bytes((ROOT / rel).read_bytes())
        toolkit_marker = decode((self.root / "toolkit.json").read_bytes())
        toolkit_marker.pop("branding", None)
        (self.root / "toolkit.json").write_bytes(encoded(toolkit_marker))
        (self.root / "README.md").write_text("# Fictional toolkit fixture\n", encoding="utf-8")
        (self.root / ".gitattributes").write_bytes(b"* -text\n")
        (self.root / "templates/export-allowlist.json").write_bytes(encoded({"files": [".gitattributes", "README.md", "toolkit.json"]}))
        try:
            self.tk = Toolkit(self.root)
        except Refusal as error:
            if private_capability_hold(error):
                self.skipTest("Actual private-workspace capability hold: " + str(error))
            raise
        self.run_id = self.tk.new_run(platform="linux")["run_id"]

    def ledger(self):
        return self.tk.read_ledger(self.run_id)

    def component(self, name="Fictional Tool"):
        return {"id": "fictional-tool", "name": name, "kind": "runtime", "installed_version": "1.0",
                "reviewed_target": None, "available_release": None, "update_state": "held",
                "security_state": "not_assessed", "compatibility_state": "not_tested", "owner_scope": "vendor_bundle",
                "evidence_ids": [], "finding_ids": [], "agent_id": "fixture-reviewer", "next_step": "Inspect official support before a change."}

    def completed(self):
        ledger = self.ledger()
        ledger["run"].update(phase="closed", status="completed")
        self.tk.set_ledger(self.run_id, ledger)

    def evidence(self, data=b"Fictional evidence only"):
        row = self.tk.write_artifact(self.run_id, "evidence/fiction.json", "evidence", data)
        ledger = self.ledger()
        ledger["evidence"].append({"id": "fiction", "relative_path": row["relative_path"], "sha256": row["sha256"],
            "kind": "fixture", "observed_utc": ledger["run"]["updated_utc"], "scope": "Fictional boundary check", "limits": "Not host evidence"})
        self.tk.set_ledger(self.run_id, ledger)

    def recovery_fixture(self, close=True):
        row = self.tk.write_artifact(self.run_id, "backups/recovery.txt", "backup", b"Fictional rollback bytes", rollback=True)
        self.evidence()
        ledger = self.ledger(); verification = self.action("completed", "verify")
        verification.update(evidence_ids=["fiction"], finished_utc=ledger["run"]["created_utc"])
        ledger["actions"] = [verification]
        if close:
            ledger["run"].update(phase="closed", status="completed")
        self.tk.set_ledger(self.run_id, ledger)
        return row

    def action(self, state="planned", kind="observe"):
        return {"id": "action-fiction", "kind": kind, "state": state, "component_ids": [], "evidence_ids": [],
                "approval_id": None, "started_utc": None, "finished_utc": None, "outcome": None, "automatic_retry": False}

    def test_new_run_does_not_collect(self):
        ledger = self.ledger()
        self.assertEqual(ledger["components"], [])
        self.assertEqual(ledger["run"]["status"], "draft")
        self.assertTrue(self.tk.validate(self.run_id)["valid"])

    def test_fixture_cannot_collect(self):
        with self.assertRaises(Refusal): self.tk.collect_baseline(self.run_id)

    def test_isolated_cli_help(self):
        result = subprocess.run([sys.executable, "-I", "-S", "-B", str(ROOT / "scripts/patchcairn.py"), "--help"],
            capture_output=True, text=True, timeout=20)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("collect-baseline", result.stdout)

    def test_copied_toolkit_isolated_cli_fixture_new_run(self):
        scripts = self.root / "scripts"; scripts.mkdir()
        for name in ("patchcairn.py", "posix_core.py", "private_workspace.py", "linux_privacy.py", "darwin_privacy.py"):
            (scripts / name).write_bytes((ROOT / "scripts" / name).read_bytes())
        command = [sys.executable, "-I", "-S", "-B", str(scripts / "patchcairn.py"), "new-run",
                   "--mode", "fixture", "--platform", "linux", "--purpose", "Fictional copied-toolkit portability check"]
        result = subprocess.run(command, capture_output=True, text=True, timeout=20)
        self.assertEqual(result.returncode, 0, result.stderr)
        returned = json.loads(result.stdout)
        marker = decode((self.root / "work" / returned["run_id"] / "run-marker.json").read_bytes())
        self.assertEqual(marker["backend"], BACKEND)
        self.assertEqual(marker["creation_mode"], "fixture")
        self.assertFalse((scripts / "__pycache__").exists())

