    def test_consistency_owner_component_reference_absent_null_and_valid(self):
        ledger = self.ledger(); parent = self.component("Fictional owning application"); parent["id"] = "parent-app"
        child = self.component("Fictional bundled runtime"); child["id"] = "child-runtime"
        ledger["components"] = [parent, child]
        self.tk.set_ledger(self.run_id, ledger)
        self.assertNotIn("owner_component_id", self.ledger()["components"][1])
        for owner_id in (None, "parent-app"):
            ledger["components"][1]["owner_component_id"] = owner_id
            self.tk.set_ledger(self.run_id, ledger)
            self.assertEqual(self.ledger()["components"][1]["owner_component_id"], owner_id)

    def test_consistency_invalid_owner_reference_preserves_canonical_bytes(self):
        ledger = self.ledger(); parent = self.component("Fictional owning application"); parent["id"] = "parent-app"
        child = self.component("Fictional bundled runtime"); child.update(id="child-runtime", owner_component_id=None)
        ledger["components"] = [parent, child]; self.tk.set_ledger(self.run_id, ledger)
        run_path = self.root / "work" / self.run_id
        original = {name: (run_path / name).read_bytes() for name in ("ledger.json", "owned-files.json", "actions.jsonl")}
        for value in ("missing-app", "PARENT-APP", "", 42, True, [], {}):
            invalid = copy.deepcopy(ledger); invalid["components"][1]["owner_component_id"] = value
            with self.subTest(value=value), self.assertRaises(Refusal):
                self.tk.set_ledger(self.run_id, invalid)
            for name, before in original.items():
                self.assertEqual((run_path / name).read_bytes(), before)

    def test_consistency_optional_component_context_requires_nullable_strings(self):
        ledger = self.ledger(); ledger["components"] = [self.component()]
        for field in ("architecture", "manager", "channel", "default_resolution"):
            for valid in (None, "fictional-context"):
                ledger["components"][0][field] = valid
                self.tk.set_ledger(self.run_id, ledger)
            invalid = copy.deepcopy(ledger); invalid["components"][0][field] = {"unexpected": "object"}
            before = (self.root / "work" / self.run_id / "ledger.json").read_bytes()
            with self.subTest(field=field), self.assertRaises(Refusal): self.tk.set_ledger(self.run_id, invalid)
            self.assertEqual((self.root / "work" / self.run_id / "ledger.json").read_bytes(), before)

