    def mocked_real_baseline_fixture(self, observations=None):
        with mock.patch.object(Toolkit, "assert_native_platform", return_value=None):
            run_id = self.tk.new_run("real", "linux", "Fictional mocked collector test; no native query")["run_id"]
        response = {"platform": "linux", "collection_mode": "real", "observed_utc": "2026-01-02T03:04:05Z",
            "observations": [{"name": "Fictional Runtime", "kind": "runtime", "version": "1.0", "scope": "system"}] if observations is None else observations,
            "limits": ["Fictional injected collector; no host inventory"]}
        collector = types.SimpleNamespace(collect=mock.Mock(return_value=response))
        return run_id, collector

    def assert_baseline_refused_without_queries_or_writes(self, run_id, collector):
        run_path = self.root / "work" / run_id
        before = {name: (run_path / name).read_bytes() for name in ("ledger.json", "owned-files.json", "actions.jsonl")}
        tree_before = sorted(p.relative_to(self.root / "work").as_posix() for p in (self.root / "work").rglob("*"))
        collector.collect.reset_mock()
        with mock.patch.object(Toolkit, "assert_native_platform", return_value=None) as native_probe, \
             mock.patch.dict(sys.modules, {"collect_linux": collector}), mock.patch.object(self.tk, "lock", wraps=self.tk.lock) as write_lock:
            with self.assertRaises(Refusal): self.tk.collect_baseline(run_id)
            collector.collect.assert_not_called(); native_probe.assert_not_called(); write_lock.assert_not_called()
        for name, value in before.items(): self.assertEqual((run_path / name).read_bytes(), value)
        self.assertEqual(sorted(p.relative_to(self.root / "work").as_posix() for p in (self.root / "work").rglob("*")), tree_before)

    def test_consistency_repeat_baseline_refuses_before_native_query_or_lock(self):
        run_id, collector = self.mocked_real_baseline_fixture()
        with mock.patch.object(Toolkit, "assert_native_platform", return_value=None), mock.patch.dict(sys.modules, {"collect_linux": collector}):
            self.tk.collect_baseline(run_id)
        collector.collect.return_value["observations"][0]["version"] = "2.0"
        self.assert_baseline_refused_without_queries_or_writes(run_id, collector)
        self.assertEqual([c["installed_version"] for c in self.tk.read_ledger(run_id)["components"]], ["1.0"])

    def test_consistency_empty_prior_baseline_still_refuses_repeat(self):
        run_id, collector = self.mocked_real_baseline_fixture([])
        with mock.patch.object(Toolkit, "assert_native_platform", return_value=None), mock.patch.dict(sys.modules, {"collect_linux": collector}):
            self.assertEqual(self.tk.collect_baseline(run_id)["observation_count"], 0)
        self.assertEqual(self.tk.read_ledger(run_id)["components"], [])
        self.assert_baseline_refused_without_queries_or_writes(run_id, collector)

    def test_consistency_interrupted_baseline_artifact_requires_fresh_run(self):
        run_id, collector = self.mocked_real_baseline_fixture()
        self.tk.write_artifact(run_id, "evidence/baseline-" + "a" * 32 + ".json", "evidence", b'{"fictional":"interrupted before canonical reconciliation"}')
        self.assert_baseline_refused_without_queries_or_writes(run_id, collector)

    def test_consistency_manual_components_require_fresh_baseline_run(self):
        run_id, collector = self.mocked_real_baseline_fixture()
        ledger = self.tk.read_ledger(run_id); ledger["components"] = [self.component()]; self.tk.set_ledger(run_id, ledger)
        self.assert_baseline_refused_without_queries_or_writes(run_id, collector)

    def test_consistency_other_evidence_allows_first_mocked_baseline(self):
        run_id, collector = self.mocked_real_baseline_fixture()
        row = self.tk.write_artifact(run_id, "evidence/preflight.json", "evidence", b'{"fictional":"preflight evidence"}')
        ledger = self.tk.read_ledger(run_id); ledger["evidence"].append({"id": "preflight", "relative_path": row["relative_path"],
            "sha256": row["sha256"], "kind": "fixture", "observed_utc": "2026-01-02T03:04:05Z", "scope": "Fictional preflight", "limits": "No host query"})
        self.tk.set_ledger(run_id, ledger)
        with mock.patch.object(Toolkit, "assert_native_platform", return_value=None), mock.patch.dict(sys.modules, {"collect_linux": collector}):
            result = self.tk.collect_baseline(run_id)
        collector.collect.assert_called_once()
        after = self.tk.read_ledger(run_id)
        self.assertEqual(result["observation_count"], 1); self.assertEqual(len(after["components"]), 1)
        self.assertEqual(len(after["evidence"]), 2); self.assertEqual(after["evidence"][0]["id"], "preflight")

