    def test_release_recovery_preserves_bytes_and_audits_consent(self):
        row = self.recovery_fixture()
        artifact = self.root / "work" / self.run_id / row["relative_path"]
        before = artifact.read_bytes()
        result = self.tk.release_recovery(self.run_id, row["relative_path"], row["sha256"], ["fiction"],
            "Release this fictional backup protection", "Fictional recovery checkpoint verified")
        self.assertFalse(result["deletion_performed"])
        self.assertEqual(artifact.read_bytes(), before)
        _, _, owned = self.tk.run(self.run_id)
        self.assertFalse(next(f for f in owned["files"] if f["relative_path"] == row["relative_path"])["rollback_needed"])
        audit = (artifact.parent.parent / "actions.jsonl").read_text()
        self.assertIn("ReleaseRecoveryCompleted", audit)
        self.assertIn("Release this fictional backup protection", audit)

