    def test_release_recovery_requires_owner_reason_evidence_and_exact_hash(self):
        row = self.recovery_fixture()
        cases = [(row["sha256"], [], "Approve", "Reason"), (row["sha256"], ["missing"], "Approve", "Reason"),
                 (row["sha256"], ["fiction"], " ", "Reason"), (row["sha256"], ["fiction"], "Approve", " "),
                 ("0" * 64, ["fiction"], "Approve", "Reason")]
        for expected, evidence_ids, quote, reason in cases:
            with self.assertRaises(Refusal): self.tk.release_recovery(self.run_id, row["relative_path"], expected, evidence_ids, quote, reason)

