    def test_private_records_and_export_stream_are_admitted_before_bytes(self):
        for path in (self.tk.work, self.tk.work / self.run_id):
            private_workspace.ensure_private_directory(path)
        for name in ("run-marker.json", "ledger.json", "owned-files.json", "actions.jsonl", "PLANS.md"):
            private_workspace.ensure_private_file(self.tk.work / self.run_id / name)
        original = core._private_existing_stream
        observed = []
        @contextlib.contextmanager
        def checked_stream(path, mode):
            if Path(path).name == "toolkit.zip" and mode == "r+b":
                self.assertEqual(Path(path).stat().st_size, 0)
                private_workspace.ensure_private_file(path)
                observed.append(mode)
            with original(path, mode) as stream:
                yield stream
        with mock.patch.object(core, "_private_existing_stream", side_effect=checked_stream):
            exported = self.tk.export_toolkit()
        self.assertEqual(observed, ["r+b"])
        private_workspace.ensure_private_file(exported["archive"])
        private_workspace.ensure_private_file(exported["manifest"])

