class LegacyPrivacyBoundaryTests(unittest.TestCase):
    """Independent negative cases do not require a usable private store."""
    def setUp(self):
        parent = ROOT / "work" / "upgrade_v3" / "filesystem" / "legacy_privacy"
        parent.mkdir(parents=True, exist_ok=True)
        self.root = parent / ("fixture-" + uuid.uuid4().hex)
        (self.root / "templates").mkdir(parents=True)
        for rel in ("toolkit.json", "templates/ledger-contract.json"):
            (self.root / rel).write_bytes((ROOT / rel).read_bytes())
        (self.root / "public.txt").write_bytes(b"Fictional public source")

    def test_foreign_filesystem_refusal_precedes_private_directory_and_bytes(self):
        helper = types.SimpleNamespace(PrivateWorkspaceError=private_workspace.PrivateWorkspaceError,
            ensure_private_directory=mock.Mock(side_effect=private_workspace.PrivateWorkspaceError("private-linux-foreign-filesystem")),
            write_private_new=mock.Mock())
        with mock.patch.object(core, "_private_api", return_value=helper):
            with self.assertRaisesRegex(Refusal, "private-linux-foreign-filesystem"):
                Toolkit(self.root)
        self.assertFalse((self.root / "work").exists())
        helper.write_private_new.assert_not_called()

    def test_export_license_exception_does_not_widen_other_names_or_text_bounds(self):
        # Public payload validation must refuse these cases before requesting
        # any private output. This is no positive private-filesystem bypass.
        toolkit = object.__new__(Toolkit)
        toolkit.root = self.root
        toolkit.area = mock.Mock(side_effect=AssertionError("Invalid source must not allocate export output"))
        listing = self.root / "templates/export-allowlist.json"
        for name in ("NOTICE", "license", "docs/LICENSE", ".GITATTRIBUTES", "docs/.gitattributes"):
            target = self.root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(b"Fictional public source")
            listing.write_bytes(encoded({"files": [name]}))
            with self.subTest(name=name), self.assertRaisesRegex(Refusal, "Unreviewed public export type"):
                toolkit.export_toolkit()
        for name in ("LICENSE", ".gitattributes"):
            for payload in (b"\xff\xfe", b"\x00", b"x" * 4_000_001):
                (self.root / name).write_bytes(payload)
                listing.write_bytes(encoded({"files": [name]}))
                with self.subTest(name=name, bytes=len(payload)), self.assertRaises(Refusal):
                    toolkit.export_toolkit()
        toolkit.area.assert_not_called()

    def test_existing_unprotected_private_scope_is_held_without_adoption(self):
        work = self.root / "work"
        work.mkdir()
        before = work.stat()
        with mock.patch.object(core.os, "chmod") as chmod:
            with self.assertRaisesRegex(Refusal, "Private storage refused"):
                Toolkit(self.root)
        self.assertEqual(list(work.iterdir()), [])
        self.assertEqual((work.stat().st_ino, work.stat().st_mode), (before.st_ino, before.st_mode))
        chmod.assert_not_called()

